syntax:
class Example {
    void memberFunction() &;  // Lvalue ref-qualifier: Callable only on lvalue objects
    void memberFunction() &&; // Rvalue ref-qualifier: Callable only on rvalue objects
    void memberFunction() const &;  // Const lvalue ref-qualifier: Callable on const lvalue objects
    // Note: Overloading is only allowed if all declarations with the same name and parameter list have ref-qualifiers; otherwise, it's ill-formed per [over.load]/1.4.
};

code_example:
#include <iostream>

class Y {
public:
    void h() & { std::cout << "Lvalue h" << std::endl; }  // Lvalue ref-qualifier
    void h() const & { std::cout << "Const lvalue h" << std::endl; }  // Const lvalue ref-qualifier
    void h() && { std::cout << "Rvalue h" << std::endl; }  // Rvalue ref-qualifier

    void i() & { std::cout << "Lvalue i" << std::endl; }  // Lvalue ref-qualifier
    // void i() const;  // This would be ill-formed; uncommenting causes a compiler error due to mixed ref-qualifiers
};

int main() {
    Y y_obj;  // Lvalue object
    y_obj.h();  // Calls void h() &
    const Y const_y_obj;  // Const lvalue object
    const_y_obj.h();  // Calls void h() const &
    Y().h();  // Rvalue object, calls void h() &&
    // y_obj.i();  // Works if uncommented, but adding non-ref-qualified i() would fail
    return 0;
}
